const worker = spawn(process.execPath,['--disable-warning=ExperimentalWarning','dist/worker.js'],{env:{...process.env,DATABASE_PATH:path},stdio:'ignore'});
await new Promise(r=>setTimeout(r,3500));
const failed = db.prepare(\"SELECT status,attempts,error FROM jobs WHERE id='interrupted'\").get();
const heart = db.prepare('SELECT updated_at FROM worker_heartbeat WHERE id=1').get();
const age = Date.now()-heart.updated_at;
worker.kill('SIGTERM'); await new Promise(r=>worker.once('exit',r));
